/**
 * 样式：CSS 文本 + 运行时注入。
 *
 * 为什么不用 `.css` 文件：DSH 客户端插件包由 tsdown 打成单个 JS，
 * 没有 CSS sidecar 加载通道（生态里的客户端插件一律用
 * `document.createElement('style')` 注入）。把 CSS 作为字符串放进 TS，
 * 保证它一定被打进 client bundle。
 *
 * 与此同时，关键几何（小圆圈的尺寸/颜色）在组件里用**内联样式**兜底：
 * 即使样式注入失败，控件仍然可见 —— 只有动画会缺失。
 *
 * ⚠️ 注入的标签**必须**带 `data-plugin` 归属：DSH 客户端模块系统按它认领与删除
 * 样式表，没有归属的标签会被**后来物化的别的插件**认领走（详见 `ensureStyles`）。
 */
/** 设计 tokens + 组件样式。 */
export declare const CONNECTION_CARD_CSS = "\n:root {\n  --ccr-perm-read: #9CA3AF;\n  --ccr-perm-suggest: #3B82F6;\n  --ccr-perm-write: #F97316;\n  --ccr-health-green: #10B981;\n  --ccr-health-yellow: #F59E0B;\n  --ccr-health-red: #EF4444;\n  --ccr-line-color: #60A5FA;\n  /* \u62C9\u7EBF\u300C\u6C34\u6D41\u300D\u4E3B\u8272\u3002\n     \u7528\u6237\u8981\u6C42\u767D\u8272\u534A\u900F\u660E\uFF1B\u4F46\u7EAF\u767D\u5728\u6D45\u8272\u4E3B\u9898\u4E0B\u4E0D\u53EF\u89C1\uFF0C\n     \u56E0\u6B64\u53D6 DSH \u7684\u4E3B\u9898 token\uFF08\u6DF1\u8272\u4E3B\u9898=\u767D\uFF0C\u6D45\u8272\u4E3B\u9898=\u6DF1\uFF09\uFF0C\u4FDD\u8BC1\u4E24\u4E2A\u4E3B\u9898\u90FD\u770B\u5F97\u89C1\u3002\n     \u60F3\u5F3A\u5236\u7EAF\u767D\u5C31\u628A\u8FD9\u91CC\u6539\u6210 #ffffff\u3002 */\n  --ccr-flow-color: var(--dsw-alias-label-primary, #ffffff);\n  /*\n   * \u26A0\uFE0F \u8FD9\u91CC\u4E00\u5EA6\u52A0\u8FC7 --ccr-rail-color / --ccr-drag-color \u4E24\u4E2A\u300C\u4E2D\u95F4\u8C03\u300D\u4EE4\u724C\uFF0C\n   * \u76EE\u7684\u662F\u8BA9\u7EBF\u5728\u660E\u4EAE\u58C1\u7EB8\u4E0A\u53EF\u89C1\u3002**\u5DF2\u5168\u90E8\u5220\u9664** \u2014\u2014\n   *\n   * \u7528\u6237\u660E\u786E\u88C1\u5B9A\uFF1A\u300C\u6211\u4EEC\u53EA\u662F\u89E3\u51B3**\u600E\u4E48\u663E\u73B0**\uFF0C\u5E76\u4E0D\u662F\u989C\u8272\u95EE\u9898\uFF01\u300D\n   * \u7EBF\u7684\u5916\u89C2\uFF08\u989C\u8272\u3001\u7EBF\u5BBD\u3001\u900F\u660E\u5EA6\uFF09\u4FDD\u6301\u521D\u7248\u539F\u6837\uFF1B\n   * \u300C\u770B\u4E0D\u89C1\u300D\u4E00\u5F8B\u8D70**\u663E\u73B0**\u90A3\u6761\u8DEF\u89E3\u51B3 = \u6302\u5230 body \u672B\u5B50\u8282\u70B9\u4E0A\u7684\u5171\u7528\u5BBF\u4E3B\n   * \uFF08\u89C1 src/ui/overlay-host.ts\uFF09\u2014\u2014 \u90A3\u624D\u662F\u771F\u6B63\u7684\u75C5\u56E0\u6240\u5728\uFF08\u5806\u53E0\u4E0A\u4E0B\u6587\uFF09\u3002\n   *\n   * \u26A0\uFE0F \u672C\u6587\u4EF6\u6574\u4F53\u662F\u4E00\u4E2A\u6A21\u677F\u5B57\u7B26\u4E32 \u2014\u2014 \u6CE8\u91CA\u91CC\u4E0D\u8981\u5199\u53CD\u5F15\u53F7\uFF08\u4F1A\u622A\u65AD\u5B57\u7B26\u4E32\uFF09\u3002\n   */\n  --ccr-fast: 150ms cubic-bezier(0.2, 0, 0, 1);\n  --ccr-panel-highlight: rgba(96, 165, 250, 0.12);\n}\n\n/* \u2550\u2550\u2550 AnchorCircle\uFF08\u51E0\u4F55\u5728\u5185\u8054\u6837\u5F0F\u91CC\uFF0C\u8FD9\u91CC\u53EA\u8865\u52A8\u6548\uFF09 \u2550\u2550\u2550 */\n.ccr-anchor {\n  animation: none;\n}\n\n.ccr-anchor__pulse {\n  position: absolute;\n  inset: -3px;\n  border-radius: 50%;\n  border: 1.5px solid var(--ccr-flow-color);\n  opacity: 0;\n  pointer-events: none;\n}\n\n.ccr-anchor--dragging .ccr-anchor__pulse {\n  animation: ccr-anchor-pulse 1200ms ease-out infinite;\n}\n\n/* \u5E45\u5EA6\u6536\u5C0F\uFF1A1 \u2192 1.45\uFF08\u539F\u6765 2 \u592A\u5927\uFF0C\u89C2\u611F\"\u4E00\u76F4\u95EA\"\uFF09 */\n@keyframes ccr-anchor-pulse {\n  0% { transform: scale(1); opacity: 0.5; }\n  100% { transform: scale(1.45); opacity: 0; }\n}\n\n/* \u2550\u2550\u2550 DragLine\uFF1A\u6C34\u6D41\u6548\u679C \u2550\u2550\u2550\n   \u4E09\u5C42\u53E0\u52A0\uFF1A\n     1. ccr-flow__glow   \u5BBD + \u9AD8\u65AF\u6A21\u7CCA + \u6781\u4F4E\u900F\u660E \u2192 \u6C34\u6C7D\u5149\u6655\n     2. ccr-flow__core   \u6E10\u53D8\u767D\u4E3B\u7EBF\uFF08\u4E24\u7AEF\u6DE1\u51FA\uFF0C\u4E0D\u662F\u786C\u90A6\u90A6\u7684\u7EBF\uFF09\n     3. ccr-flow__band   \u77ED\u5212\u7EBF\u6CBF\u8DEF\u5F84\u6ED1\u52A8 \u2192 \u6C34\u5728\u6D41\n   \u7C92\u5B50\uFF08\u6C34\u73E0\uFF09\u7531\u7EC4\u4EF6\u5185\u8054\u6E32\u67D3\u3002 */\n.ccr-drag-line {\n  position: fixed;\n  inset: 0;\n  pointer-events: none;\n  z-index: 9999;\n  overflow: visible;\n}\n\n.ccr-flow__glow {\n  fill: none;\n  stroke: var(--ccr-flow-color);\n  stroke-width: 7px;\n  stroke-opacity: 0.16;\n  stroke-linecap: round;\n}\n\n.ccr-flow__core {\n  fill: none;\n  stroke-linecap: round;\n}\n\n.ccr-flow__band {\n  fill: none;\n  stroke: var(--ccr-flow-color);\n  stroke-width: 1.2px;\n  stroke-opacity: 0.5;\n  stroke-linecap: round;\n  stroke-dasharray: 34 58;\n  animation: ccr-water-flow 1100ms linear infinite;\n}\n\n@keyframes ccr-water-flow {\n  to { stroke-dashoffset: -92; }\n}\n\n.ccr-flow__particle {\n  fill: var(--ccr-flow-color);\n}\n\n/* \u2550\u2550\u2550 SessionRailOverlay\uFF1A\u4F1A\u8BDD\u884C\u4E0A\u7684\u7AD6\u7EBF\uFF08\u98CE\u683C\u5BF9\u9F50\u62D6\u62FD\u7684\u6C34\u6D41\u7EBF\uFF09 \u2550\u2550\u2550\n *\n * \u53EA\u6709\u6D41\u52A8\u52A8\u753B\u548C keyframes \u662F\u6D3B\u7684 \u2014\u2014 \u4E0B\u9762\u7684 .ccr-rail / .ccr-rail__overflow /\n * .ccr-lane* \u5C5E\u4E8E\u5DF2\u5220\u9664\u7684 SessionRail/RailLane \u7EC4\u4EF6\uFF08\u90A3\u5957\u7528\u7EDD\u5BF9\u5B9A\u4F4D\u7684\n * div \u753B\u7EBF\uFF0C\u65E9\u5DF2\u88AB SVG \u7684 SessionRailOverlay \u53D6\u4EE3\uFF09\uFF0C\u7559\u7740\u53EA\u4F1A\u8BEF\u5BFC\u4EBA\u3002 */\n.ccr-rail__flow {\n  animation: ccr-rail-flow 2600ms linear infinite;\n}\n\n@keyframes ccr-rail-flow {\n  to { stroke-dashoffset: -36; }\n}\n\n/* \u2550\u2550\u2550 \u62D6\u62FD\u843D\u70B9\u63D0\u793A\uFF08\u547D\u4E2D\u5DE6\u4FA7\u4F1A\u8BDD\u884C\uFF09 \u2550\u2550\u2550 */\n.ccr-target {\n  background: var(--ccr-panel-highlight) !important;\n  box-shadow: inset 2px 0 0 var(--ccr-flow-color) !important;\n}\n\n/* \u5DF2\u8FDE\u7684\u76EE\u6807\uFF1A\u677E\u624B\u4F1A\u65AD\u5F00\uFF0C\u7528\u7EA2\u8C03\u533A\u5206\u4E8E\u300C\u4F1A\u8FDE\u63A5\u300D */\n.ccr-target--disconnect {\n  background: rgba(239, 68, 68, 0.13) !important;\n  box-shadow: inset 2px 0 0 #EF4444 !important;\n}\n\n/* \u2550\u2550\u2550 \u9762\u677F\uFF08main \u69FD\u4F4D\uFF0C\u6574\u9875\u5BBD\u5EA6\uFF09 \u2550\u2550\u2550 */\n/*\n * \u5916\u5C42\uFF1A\u4E3B\u5185\u5BB9 + \u53F3\u4FA7\u63D2\u4EF6 UI \u4FA7\u680F\u3002\n *\n * \u9762\u677F\u4E3B\u4F53\u4ECD\u662F ccr-page\uFF08720 \u5C45\u4E2D\uFF09\uFF0C\u4FA7\u680F\u5360\u7528\u53F3\u8FB9\u7684\u7559\u767D \u2014\u2014\n * \u9002\u914D\u5361\u63D2\u4EF6\u7684 UI \u5C31\u6E32\u67D3\u5728\u90A3\u513F\uFF08\u800C\u4E0D\u662F DSH \u5168\u5C40\u754C\u9762\uFF09\u3002\n * \u6CA1\u6709\u9002\u914D\u5361\u65F6\u4FA7\u680F\u4E0D\u6E32\u67D3\uFF0C\u5E03\u5C40\u4E0E\u4EE5\u524D**\u5B8C\u5168\u4E00\u81F4**\uFF08justify-content: center \u8BA9\u4E3B\u4F53\u5C45\u4E2D\uFF09\u3002\n *\n * \u26A0\uFE0F\u26A0\uFE0F height:100% \u4E0E min-height:0 **\u5FC5\u987B\u7559\u7740**\u3002\n *\n * \u8FD9\u5C42\u662F\u600E\u4E48\u6765\u7684\uFF1A\u4EE5\u524D ccr-page \u662F\u5BBF\u4E3B main \u533A\u7684**\u76F4\u63A5\u5B50\u9879**\uFF0C\u9760 height:100%\n * \u62FF\u5230\u5B9A\u9AD8\u3001\u6210\u4E3A\u6EDA\u52A8\u5BB9\u5668\u3002\u52A0\u4E86\u8FD9\u5C42\u4E4B\u540E ccr-page \u53D8\u6210**\u5B83\u7684**\u5B50\u9879 \u2014\u2014\n * \u800C\u5B83\u9ED8\u8BA4\u9AD8\u5EA6 auto\uFF0C\u4E8E\u662F ccr-page \u7684 height:100% \u9000\u5316\u6210 auto\u3001\n * **\u4E0D\u518D\u662F\u6EDA\u52A8\u5BB9\u5668**\uFF0C\u5916\u5C42\u4E5F\u4E0D\u6EDA \u21D2 **\u6EDA\u8F6E\u5B8C\u5168\u6CA1\u53CD\u5E94**\uFF08\u7528\u6237\u5B9E\u6D4B\u62A5\u4E0A\u6765\u7684\u56DE\u5F52\uFF09\u3002\n *\n * \u6240\u4EE5\u8FD9\u91CC\u8981\u628A\u5BBF\u4E3B\u7ED9\u7684\u9AD8\u5EA6**\u63A5\u4F4F\u518D\u5F80\u4E0B\u4F20**\uFF1Bflex \u9879\u8FD8\u8981 min-height:0\n * \u624D\u80FD\u6536\u7F29\uFF08\u5426\u5219\u5185\u5BB9\u628A\u5B83\u6491\u9AD8\uFF0C\u4E00\u6837\u6EDA\u4E0D\u52A8\uFF09\u3002\n */\n.ccr-page-wrap {\n  display: flex;\n  justify-content: center;\n  align-items: flex-start;\n  gap: 16px;\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n}\n/* \u7A84\u5C4F\u65F6\u4FA7\u680F\u6362\u884C\u5230\u4E0B\u65B9\uFF0C\u907F\u514D\u628A\u4E3B\u5185\u5BB9\u6324\u7A84 */\n@media (max-width: 1100px) {\n  .ccr-page-wrap { flex-wrap: wrap; height: auto; }\n  .ccr-page__side { width: 100%; max-width: 720px; margin: 0 auto 24px; height: auto; }\n}\n.ccr-page__side {\n  box-sizing: border-box;\n  width: 300px;\n  padding: 24px 12px 40px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  /* \u4FA7\u680F\u81EA\u5DF1\u4E5F\u6EDA\uFF1A\u63D2\u4EF6 UI \u53EF\u80FD\u5F88\u9AD8\uFF0C\u4E0D\u80FD\u628A\u9762\u677F\u6491\u6210\u4E0D\u53EF\u6EDA */\n  height: 100%;\n  min-height: 0;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n}\n/* \u6355\u83B7\u5230\u7684\u63D2\u4EF6 UI\uFF1A\u4E0E\u9762\u677F\u540C\u7528\u4E3B\u9898\u4EE4\u724C\uFF0C\u4E0D\u5199\u6B7B\u989C\u8272 */\n.ccr-captured {\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128, 128, 128, 0.25));\n  border-radius: 8px;\n  padding: 10px 12px;\n  background: var(--dsw-alias-bg-l1, transparent);\n}\n.ccr-captured__head {\n  font-size: 11px;\n  opacity: 0.65;\n  margin-bottom: 8px;\n  word-break: break-all;\n}\n.ccr-captured__slot {\n  font-size: 10px;\n  opacity: 0.45;\n  margin: 8px 0 4px;\n}\n.ccr-captured__note,\n.ccr-captured__error {\n  font-size: 11px;\n  opacity: 0.7;\n  padding: 8px 10px;\n  border: 1px dashed var(--dsw-alias-border-l1, rgba(128, 128, 128, 0.35));\n  border-radius: 8px;\n  word-break: break-word;\n}\n.ccr-page {\n  box-sizing: border-box;\n  width: 100%;\n  max-width: 720px;\n  margin: 0 auto;\n  padding: 24px 20px 40px;\n  color: var(--dsw-alias-label-primary, inherit);\n  font-size: 13px;\n  /*\n   * \u9762\u677F\u81EA\u5DF1\u505A\u6EDA\u52A8\u5BB9\u5668\u3002\n   *\n   * \u4E3A\u4EC0\u4E48\u5FC5\u987B\uFF1A\u5185\u5BB9\u4F1A\u8D85\u8FC7\u4E00\u5C4F\uFF08\u8FDE\u63A5\u591A\u4E86\u3001\u6BCF\u6761\u5C55\u5F00\u8FD8\u6709\u5361\u7247+\u611F\u77E5\u533A\uFF09\uFF0C\n   * \u800C\u5BBF\u4E3B\u7684 main \u533A**\u4E0D\u4FDD\u8BC1\u662F\u6EDA\u52A8\u5BB9\u5668** \u2014\u2014 \u4E4B\u524D\u6CA1\u6709\u9AD8\u5EA6\u7EA6\u675F\u4E5F\u6CA1 overflow\uFF0C\n   * \u4E8E\u662F\u8D85\u51FA\u90E8\u5206\u76F4\u63A5\u88AB\u88C1\u6389\uFF0C\u6EDA\u8F6E\u5B8C\u5168\u6CA1\u53CD\u5E94\u3002\n   *\n   * height/max-height \u90FD\u5199\uFF1A\u7236\u7EA7\u82E5\u662F\u5B9A\u9AD8 flex/grid \u9879\uFF0Cheight:100% \u751F\u6548\uFF1B\n   * \u82E5\u662F\u81EA\u52A8\u9AD8\u5EA6\uFF0C\u4E24\u8005\u90FD\u9000\u5316\u6210 auto\uFF0C\u884C\u4E3A\u4E0E\u4FEE\u590D\u524D\u4E00\u81F4\uFF08\u4E0D\u4F1A\u66F4\u7CDF\uFF09\u3002\n   */\n  height: 100%;\n  max-height: 100%;\n  overflow-y: auto;\n  overscroll-behavior: contain;\n}\n\n.ccr-page__head { margin-bottom: 20px; }\n\n.ccr-page__title {\n  margin: 0 0 6px;\n  font-size: 17px;\n  font-weight: 600;\n}\n\n.ccr-page__sub {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.6;\n  color: var(--dsw-alias-label-secondary, #888);\n}\n\n.ccr-block {\n  margin-bottom: 22px;\n  padding: 14px 16px;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 10px;\n}\n\n.ccr-block__title {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin: 0 0 12px;\n  font-size: 13px;\n  font-weight: 600;\n}\n\n.ccr-count {\n  padding: 0 6px;\n  border-radius: 8px;\n  background: var(--ccr-panel-highlight);\n  font-size: 11px;\n  font-weight: 500;\n}\n\n/* \u2500\u2500\u2500 \u8868\u5355 \u2500\u2500\u2500 */\n.ccr-form {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  flex-wrap: wrap;\n}\n\n.ccr-select,\n.ccr-input {\n  flex: 1 1 160px;\n  min-width: 0;\n  box-sizing: border-box;\n  padding: 6px 8px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  background: var(--dsw-alias-bg-layer-2, rgba(128,128,128,0.08));\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.3));\n  border-radius: 6px;\n}\n\n.ccr-form__sep { opacity: 0.5; }\n\n/* \u65B0\u5EFA\u8FDE\u63A5\u4E2D\u95F4\u7684\u53EF\u70B9\u8FDE\u63A5\u7B26\u3002\n   \u9ED8\u8BA4\u5916\u89C2\u4E0E\u666E\u901A \u2194 \u5206\u9694\u7B26\u4E00\u81F4\uFF08\u65E0\u6846\u3001\u65E0\u5E95\u8272\uFF09\uFF1B\n   \u60AC\u6D6E\u65F6\u51FA\u73B0\u8FB9\u6846\u4E0E\u5E95\u8272\uFF0C\u5E76\u6D6E\u51FA\u4E00\u4E2A + / \u2212 \u63D0\u793A\u53EF\u4EE5\u589E\u5220\u4E00\u4E2A\u4F1A\u8BDD\u69FD\u4F4D\u3002 */\n.ccr-form__join {\n  display: inline-flex;\n  align-items: center;\n  gap: 1px;\n  flex: none;\n  padding: 2px 5px;\n  font: inherit;\n  font-size: 12px;\n  line-height: 1;\n  color: inherit;\n  background: transparent;\n  border: 1px solid transparent;\n  border-radius: 6px;\n  cursor: pointer;\n  transition: background 120ms ease, border-color 120ms ease;\n}\n\n.ccr-form__join-arrow { opacity: 0.5; }\n\n.ccr-form__join-mark {\n  font-size: 11px;\n  opacity: 0;\n  transform: translateX(-2px);\n  transition: opacity 120ms ease, transform 120ms ease;\n}\n\n.ccr-form__join:hover {\n  background: var(--ccr-panel-highlight);\n  border-color: var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.4));\n}\n\n.ccr-form__join:hover .ccr-form__join-arrow { opacity: 0.9; }\n\n.ccr-form__join:hover .ccr-form__join-mark {\n  opacity: 1;\n  transform: translateX(0);\n}\n\n/* \u5C0F\u53F7\u5206\u6BB5\u63A7\u4EF6\uFF08\u8F68\u9053\u7EBF\u8DEF\u5F00\u5173\uFF09 */\n.ccr-seg--small .ccr-seg__item {\n  padding: 2px 8px;\n  font-size: 11px;\n}\n\n.ccr-rail-toggle { margin-left: auto; }\n\n.ccr-btn {\n  padding: 6px 14px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  background: transparent;\n  border: 1px solid var(--dsw-alias-border-l2, rgba(128,128,128,0.4));\n  border-radius: 6px;\n  cursor: pointer;\n}\n\n.ccr-btn:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-btn:disabled { opacity: 0.45; cursor: default; }\n\n.ccr-btn--primary {\n  border-color: var(--ccr-flow-color);\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-btn--danger:hover:not(:disabled) {\n  background: rgba(239, 68, 68, 0.14);\n  border-color: #EF4444;\n}\n\n.ccr-link {\n  margin-top: 8px;\n  padding: 0;\n  font: inherit;\n  font-size: 11px;\n  color: inherit;\n  opacity: 0.6;\n  background: none;\n  border: 0;\n  cursor: pointer;\n  text-decoration: underline;\n}\n\n.ccr-hint,\n.ccr-field__hint {\n  margin: 8px 0 0;\n  font-size: 11px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-secondary, #888);\n  opacity: 0.85;\n}\n\n/* \u2500\u2500\u2500 \u63D0\u793A\u6761 \u2500\u2500\u2500 */\n.ccr-notice,\n.ccr-empty,\n.ccr-error {\n  margin-bottom: 12px;\n  padding: 8px 12px;\n  border-radius: 6px;\n  font-size: 12px;\n}\n\n.ccr-notice { background: var(--ccr-panel-highlight); }\n.ccr-empty { color: var(--dsw-alias-label-secondary, #888); padding-left: 0; }\n.ccr-error { color: #EF4444; padding-left: 0; }\n\n/* \u2500\u2500\u2500 \u8FDE\u63A5\u5361\u7247 \u2500\u2500\u2500 */\n.ccr-list { display: flex; flex-direction: column; gap: 6px; }\n\n.ccr-conn {\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.ccr-conn--open { background: var(--dsw-alias-bg-layer-1, rgba(128,128,128,0.05)); }\n\n.ccr-conn__head {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  box-sizing: border-box;\n  padding: 10px 12px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  text-align: left;\n  background: none;\n  border: 0;\n  cursor: pointer;\n}\n\n.ccr-conn__head:hover { background: var(--ccr-panel-highlight); }\n\n.ccr-dot {\n  flex: none;\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n}\n\n.ccr-conn__pair {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  min-width: 0;\n}\n\n.ccr-conn__session {\n  max-width: 180px;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.ccr-conn__arrow { opacity: 0.45; }\n\n.ccr-conn__meta {\n  margin-left: auto;\n  flex: none;\n  font-size: 11px;\n  color: var(--dsw-alias-label-secondary, #888);\n}\n\n.ccr-chevron { flex: none; opacity: 0.45; font-size: 10px; }\n\n.ccr-conn__body {\n  padding: 4px 12px 12px;\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.2));\n}\n\n.ccr-field { margin: 12px 0; }\n\n.ccr-field__label {\n  margin-bottom: 6px;\n  font-size: 12px;\n  font-weight: 500;\n}\n\n.ccr-seg {\n  display: inline-flex;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.3));\n  border-radius: 6px;\n  overflow: hidden;\n}\n\n.ccr-seg__item {\n  padding: 5px 14px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  background: none;\n  border: 0;\n  border-right: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  cursor: pointer;\n  opacity: 0.7;\n}\n\n.ccr-seg__item:last-child { border-right: 0; }\n.ccr-seg__item:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-seg__item--active { background: var(--ccr-panel-highlight); opacity: 1; font-weight: 500; }\n.ccr-seg__item:disabled { cursor: default; opacity: 0.4; }\n\n.ccr-conn__actions { display: flex; gap: 8px; margin-top: 12px; }\n\n.ccr-card-stack { margin: 12px 0; }\n\n/* \u2550\u2550\u2550 \u5361\u7247\u533A \u2550\u2550\u2550 */\n.ccr-cards { margin: 12px 0; }\n\n.ccr-cards__picker {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  margin-bottom: 8px;\n  padding: 8px;\n  border: 1px dashed var(--dsw-alias-border-l2, rgba(128,128,128,0.4));\n  border-radius: 8px;\n}\n\n.ccr-card-option {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 2px;\n  padding: 8px 10px;\n  font: inherit;\n  color: inherit;\n  text-align: left;\n  background: transparent;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 6px;\n  cursor: pointer;\n}\n\n.ccr-card-option:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-card-option:disabled { opacity: 0.45; cursor: default; }\n\n/*\n * \u9002\u914D\u5361\uFF08\u666E\u901A DSH \u63D2\u4EF6\u6302\u6210\u8FDE\u63A5\u80FD\u529B\uFF09\u2014\u2014 \u7528\u6237\u88C1\u51B3 D6\uFF1A\n * **\u7167\u5E38\u5217\u51FA + \u300C\u9002\u914D\u300D\u6807\u6CE8**\uFF1B\u672A\u5C31\u7EEA\u65F6\u7F6E\u7070\uFF08\u6CBF\u7528\u4E0A\u9762\u7684 :disabled \u6837\u5F0F\uFF09\u5E76\u4FDD\u7559\u60AC\u505C\u8BF4\u660E\u3002\n * \u7F6E\u7070\u800C\u4E0D\u662F\u9690\u85CF\uFF1A\u8BA9\u7528\u6237\u77E5\u9053\"\u4E1C\u897F\u5728\u8FD9\u513F\u3001\u9700\u8981\u5F00\u4E00\u4E0B\"\uFF0C\u800C\u4E0D\u662F\u4EE5\u4E3A\u6CA1\u88C5\u4E0A\u3002\n */\n.ccr-card-option--blocked { border-style: dashed; }\n.ccr-badge {\n  display: inline-block;\n  margin-left: 6px;\n  padding: 0 5px;\n  font-size: 10px;\n  font-weight: 500;\n  line-height: 15px;\n  vertical-align: 1px;\n  border-radius: 4px;\n  /* \u4E0E\u4E3B\u9898\u4E00\u81F4\uFF1A\u7528\u8FB9\u6846\u5C42\u7EA7\u8272\uFF0C\u4E0D\u5199\u6B7B\u5177\u4F53\u989C\u8272 */\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128, 128, 128, 0.35));\n  color: var(--dsw-alias-label-secondary, rgba(255, 255, 255, 0.75));\n}\n.ccr-badge--adapter { letter-spacing: 0.5px; }\n.ccr-card-option__name { font-size: 12px; font-weight: 500; }\n/* \u5361\u7247\u66F4\u65B0\u5165\u53E3\uFF08\u5DF2\u5B89\u88C5\u5361\u7247\u624D\u6709\uFF09\uFF1A\u70B9\u4E00\u6B21\u68C0\u67E5\uFF0C\u6709\u65B0\u7248\u518D\u70B9\u4E00\u6B21\u66F4\u65B0 */\n.ccr-card-option__upd {\n  flex: none;\n  margin-left: 8px;\n  padding: 1px 6px;\n  border-radius: 4px;\n  font-size: 10px;\n  opacity: 0.7;\n  background: rgba(128, 128, 128, 0.16);\n  cursor: pointer;\n  white-space: nowrap;\n}\n.ccr-card-option__upd:hover { opacity: 1; background: rgba(128, 128, 128, 0.28); }\n\n.ccr-card-option__meta { font-size: 11px; opacity: 0.6; }\n\n.ccr-card {\n  margin-top: 6px;\n  border: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.25));\n  border-radius: 8px;\n  overflow: hidden;\n}\n\n.ccr-card__head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 10px;\n  font-size: 12px;\n}\n\n/* \u300C\u5361\u7247\u300D+ \u53F3\u4FA7\u5C0F\u4E09\u89D2\uFF1A\u70B9\u6587\u5B57\u6216\u4E09\u89D2\u90FD\u6536\u8D77/\u5C55\u5F00\u6574\u4E2A\u5361\u7247\u533A */\n.ccr-cards__toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 4px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n.ccr-cards__toggle:hover .ccr-field__label { opacity: 1; }\n.ccr-cards__tri {\n  font-size: 9px;\n  line-height: 1;\n  opacity: 0.65;\n}\n.ccr-cards__toggle:hover .ccr-cards__tri { opacity: 1; }\n\n/* \u6536\u8D77\u65F6\u53EA\u5269\u6807\u9898\u90A3\u4E00\u884C \u2014\u2014 \u53BB\u6389\u591A\u4F59\u7684\u4E0A\u4E0B\u7559\u767D */\n.ccr-cards--folded { margin-bottom: 12px; }\n\n/*\n * \u5361\u7247\u533A\u6807\u9898\u884C\uFF1A\u5361\u7247 \u25B8 3 \u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026\u2026 + \u6DFB\u52A0\u5361\u7247\n *\n * \u26A0\uFE0F display:flex \u662F**\u5FC5\u9700**\u7684 \u2014\u2014 \u300C+ \u6DFB\u52A0\u5361\u7247\u300D\u9760 margin-left:auto \u9876\u5230\u53F3\u8FB9\uFF0C\n * \u800C auto \u5916\u8FB9\u8DDD\u53EA\u5728 flex/grid \u5BB9\u5668\u91CC\u751F\u6548\u3002\u5C11\u4E86\u5B83\uFF0C\u6309\u94AE\u4F1A\u6324\u5728\u8BA1\u6570\u540E\u9762\n * \uFF08\u7528\u6237\u622A\u56FE\u91CC\u5C31\u662F\u8FD9\u6837\uFF09\u3002\n */\n/*\n * \u53EF\u5173\u95ED\u7684\u8BF4\u660E\u5757\uFF08DismissibleHint\uFF09\u2014\u2014 \u53F3\u4E0A\u89D2\u4E00\u4E2A \u00D7\uFF0C\u5173\u6389\u540E\u4E0D\u518D\u663E\u793A\u3002\n * \u5916\u5C42 relative\uFF0C\u00D7 \u7EDD\u5BF9\u5B9A\u4F4D\u5230\u53F3\u4E0A\u89D2\uFF1B\u6B63\u6587\u7559\u51FA\u53F3\u4E0A\u89D2\u7A7A\u95F4\uFF0C\u522B\u9876\u5230 \u00D7 \u5E95\u4E0B\u3002\n */\n.ccr-dismissible { position: relative; }\n.ccr-dismissible__close {\n  position: absolute;\n  top: -2px;\n  right: 0;\n  width: 18px;\n  height: 18px;\n  padding: 0;\n  border: 0;\n  border-radius: 4px;\n  background: transparent;\n  color: inherit;\n  font-size: 13px;\n  line-height: 1;\n  opacity: 0.4;\n  cursor: pointer;\n}\n.ccr-dismissible__close:hover { opacity: 0.9; background: rgba(128, 128, 128, 0.18); }\n.ccr-dismissible .ccr-field__hint { padding-right: 22px; }\n.ccr-cards__head {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n.ccr-cards__add { margin-left: auto; }\n\n/* \u5361\u7247\u9762\u677F\u7684\u6536\u8D77/\u5C55\u5F00\u7BAD\u5934\uFF08\u9ED8\u8BA4\u6536\u8D77\uFF0C\u89C1 CardStack \u7684 expandedCards\uFF09 */\n.ccr-card__toggle {\n  flex: none;\n  width: 16px;\n  height: 16px;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: inherit;\n  font-size: 10px;\n  line-height: 1;\n  opacity: 0.6;\n  cursor: pointer;\n}\n.ccr-card__toggle:hover:not(:disabled) { opacity: 1; }\n.ccr-card__toggle:disabled { opacity: 0.2; cursor: default; }\n\n.ccr-card__name { font-weight: 500; }\n\n.ccr-card__meta {\n  font-size: 11px;\n  opacity: 0.5;\n  margin-right: auto;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 40%;\n}\n\n.ccr-card__panel {\n  padding: 8px 10px 10px;\n  border-top: 1px solid var(--dsw-alias-border-l1, rgba(128,128,128,0.18));\n  font-size: 12px;\n}\n\n/* \u2550\u2550\u2550 \u6743\u9650\uFF08\u4E24\u4E2A\u65B9\u5411\u53EF\u5206\u522B\u8BBE\u7F6E\uFF09 \u2550\u2550\u2550 */\n.ccr-perm-row {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  margin-bottom: 6px;\n  min-width: 0;\n}\n\n.ccr-perm-row__who {\n  display: flex;\n  align-items: baseline;\n  gap: 5px;\n  min-width: 0;\n  flex: 1 1 auto;\n}\n\n.ccr-perm-row__name {\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 42%;\n  font-size: 12px;\n}\n\n.ccr-perm-row__verb {\n  flex: none;\n  font-size: 13px;\n  line-height: 1;\n  opacity: 0.45;\n}\n\n.ccr-perm-row__target {\n  flex: 1 1 auto;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  max-width: 42%;\n  font-size: 12px;\n  opacity: 0.85;\n}\n\n.ccr-perm-row .ccr-seg { flex: none; }\n\n/* \u2550\u2550\u2550 \u8F6C\u53D1\u4E2D\u8B66\u544A\uFF08\u6743\u9650\u9AD8\u4E8E\u53EA\u8BFB\u65F6\u5E38\u9A7B\uFF09 \u2550\u2550\u2550\n   \u7406\u7531\uFF1A\u7528\u6237\u62AC\u6743\u9650\u65F6\u4EE5\u4E3A\"\u8FD9\u662F\u8BA9\u5BF9\u65B9\u80FD\u5E72\u6D3B\"\uFF0C\u5B9E\u9645\u662F\"\u4E24\u8FB9\u8BF4\u7684\u8BDD\u5F00\u59CB\u4E92\u76F8\u704C\"\u3002\n   2026-09-30 \u56E0\u6B64\u8FDE\u7740\u4E24\u6B21\u88AB\u610F\u5916\u6253\u6270\uFF0C\u6240\u4EE5\u8FD9\u4E2A\u72B6\u6001\u5FC5\u987B\u663E\u773C\u3002 */\n.ccr-forward-warn {\n  display: flex;\n  align-items: flex-start;\n  gap: 8px;\n  margin: 10px 0;\n  padding: 9px 11px;\n  font-size: 12px;\n  line-height: 1.55;\n  border-radius: 7px;\n  background: rgba(249, 115, 22, 0.13);\n  border: 1px solid rgba(249, 115, 22, 0.35);\n}\n\n.ccr-forward-warn__dot {\n  flex: none;\n  width: 7px;\n  height: 7px;\n  margin-top: 5px;\n  border-radius: 50%;\n  background: #F97316;\n  box-shadow: 0 0 0 3px rgba(249, 115, 22, 0.2);\n}\n\n/* \u2550\u2550\u2550 \u5361\u7247\u5B89\u88C5\uFF08\u88C5\u5230\u6211\u4EEC\u81EA\u5DF1\u7684\u76EE\u5F55\uFF09 \u2550\u2550\u2550 */\n.ccr-install {\n  margin-top: 8px;\n  padding-top: 8px;\n  border-top: 1px dashed var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.25));\n}\n\n.ccr-install__row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.ccr-install__row .ccr-input { flex: 1 1 auto; min-width: 0; }\n\n/* \u76EE\u5F55\u8DEF\u5F84\u53EF\u80FD\u5F88\u957F\uFF0C\u5141\u8BB8\u6298\u884C\u4E14\u7528\u7B49\u5BBD\u5B57\u4F53\uFF0C\u907F\u514D\u770B\u6210\u4E00\u4E32\u7CCA\u5B57 */\n.ccr-install code {\n  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;\n  font-size: 10px;\n  word-break: break-all;\n}\n\n/* \u2550\u2550\u2550 \u5361\u7247\u53EF\u89C1\u8303\u56F4\uFF08\u4E24\u7AEF / \u4EC5 A / \u4EC5 B\uFF09 \u2550\u2550\u2550 */\n.ccr-scope-pick {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 2px 2px 8px;\n  margin-bottom: 6px;\n  border-bottom: 1px solid var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.2));\n}\n\n.ccr-scope-pick__label {\n  flex: none;\n  font-size: 11px;\n  opacity: 0.65;\n}\n\n/* \u5361\u7247\u5934\u91CC\u7684\u8303\u56F4\u5207\u6362\uFF1A\u9760\u53F3\u6324\u5728\u91CD\u8F7D/\u79FB\u9664\u524D\uFF0C\u4E0D\u4E0E\u540D\u5B57\u62A2\u5BBD\u5EA6 */\n.ccr-card__scope { flex: none; }\n\n.ccr-card__scope-fixed {\n  flex: none;\n  padding: 1px 6px;\n  font-size: 10px;\n  line-height: 15px;\n  border-radius: 4px;\n  background: rgba(128, 128, 128, 0.2);\n  opacity: 0.8;\n}\n\n/* \u2550\u2550\u2550 \u53EF\u6298\u53E0\u533A\u5757\uFF08\u534F\u4F5C\u611F\u77E5\u7684\u4E24\u5757\uFF09 \u2550\u2550\u2550 */\n.ccr-fold {\n  margin-top: 10px;\n  border-radius: 7px;\n  background: var(--ccr-panel-highlight);\n  overflow: hidden;\n}\n\n.ccr-fold__head {\n  display: flex;\n  align-items: center;\n  gap: 7px;\n  width: 100%;\n  padding: 7px 10px;\n  font: inherit;\n  font-size: 12px;\n  color: inherit;\n  text-align: left;\n  background: transparent;\n  border: 0;\n  cursor: pointer;\n}\n\n.ccr-fold__head:hover { background: rgba(128, 128, 128, 0.08); }\n\n.ccr-fold__chevron {\n  flex: none;\n  width: 10px;\n  font-size: 10px;\n  opacity: 0.6;\n}\n\n.ccr-fold__title {\n  flex: none;\n  font-weight: 600;\n}\n\n/* \u300C\u5BF9\u65B9\u6B63\u5728\u6D3B\u52A8\u300D\u7684\u5C0F\u5706\u70B9 \u2014\u2014 \u6536\u8D77\u72B6\u6001\u4E0B\u4E5F\u80FD\u4E00\u773C\u770B\u51FA\u5BF9\u65B9\u5728\u5FD9 */\n.ccr-fold__live {\n  flex: none;\n  width: 6px;\n  height: 6px;\n  border-radius: 50%;\n  background: #22C55E;\n  box-shadow: 0 0 0 3px rgba(34, 197, 94, 0.18);\n}\n\n/* \u6536\u8D77\u65F6\u7684\u6458\u8981\uFF1A\u5360\u6EE1\u5269\u4F59\u5BBD\u5EA6\u3001\u8D85\u51FA\u7701\u7565\uFF0C\u4E0D\u6362\u884C\uFF08\u4FDD\u8BC1\u6807\u9898\u884C\u6C38\u8FDC\u53EA\u5360\u4E00\u884C\uFF09 */\n.ccr-fold__digest {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  font-size: 11px;\n  opacity: 0.6;\n}\n\n.ccr-fold__body {\n  padding: 2px 10px 10px;\n}\n\n/* \u2550\u2550\u2550 \u534F\u4F5C\u611F\u77E5 A\uFF1A\u5DE5\u4F5C\u72B6\u6001 \u2550\u2550\u2550 */\n.ccr-field__auto,\n.ccr-field__count {\n  margin-left: 6px;\n  padding: 0 5px;\n  font-size: 10px;\n  line-height: 15px;\n  border-radius: 4px;\n  opacity: 0.7;\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-work {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-top: 4px;\n}\n\n.ccr-work__row {\n  padding: 7px 9px;\n  border-radius: 7px;\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-work__head {\n  display: flex;\n  align-items: baseline;\n  gap: 8px;\n  margin-bottom: 3px;\n}\n\n.ccr-work__name {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  font-size: 12px;\n  font-weight: 600;\n}\n\n.ccr-work__age {\n  flex: none;\n  font-size: 10px;\n  opacity: 0.6;\n}\n\n/* \u592A\u4E45\u6CA1\u66F4\u65B0\uFF1A\u72B6\u6001\u53EF\u80FD\u5DF2\u7ECF\u4E0D\u4EE3\u8868\u73B0\u72B6\u4E86\uFF0C\u5F31\u5316\u5B83 */\n.ccr-work__age--stale { opacity: 0.4; }\n\n.ccr-work__action {\n  font-size: 12px;\n  opacity: 0.9;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.ccr-work__action--empty { opacity: 0.45; font-style: italic; }\n\n.ccr-work__todos {\n  margin: 5px 0 0;\n  padding: 0;\n  list-style: none;\n}\n\n.ccr-work__todo {\n  font-size: 11px;\n  line-height: 1.5;\n  opacity: 0.8;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.ccr-work__todo--completed { opacity: 0.4; text-decoration: line-through; }\n.ccr-work__todo--in_progress { opacity: 1; font-weight: 600; }\n\n.ccr-work__files {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 4px;\n  margin-top: 5px;\n}\n\n.ccr-work__file {\n  padding: 1px 5px;\n  font-size: 10px;\n  border-radius: 4px;\n  background: rgba(128, 128, 128, 0.18);\n  opacity: 0.85;\n}\n\n.ccr-work__progress {\n  margin-top: 4px;\n  font-size: 10px;\n  opacity: 0.55;\n}\n\n/* \u4E2D\u7EE7\u8BCA\u65AD\uFF1A\u88AB\u6321\u4E0B\u7684\u975E\u771F\u4EBA\u6765\u6E90\uFF08\u5E73\u65F6\u4E0D\u663E\u793A\uFF0C\u6709\u4E1C\u897F\u88AB\u6321\u624D\u51FA\u73B0\uFF09 */\n.ccr-work__diag {\n  margin-top: 8px;\n  padding-top: 6px;\n  border-top: 1px dashed var(--dsw-alias-border-l2, rgba(128, 128, 128, 0.22));\n  font-size: 10px;\n  opacity: 0.55;\n}\n\n.ccr-work__diag-head { word-break: break-word; }\n\n.ccr-work__diag-item {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  margin-top: 3px;\n}\n\n.ccr-work__diag-kind {\n  flex: none;\n  padding: 0 4px;\n  border-radius: 3px;\n  background: rgba(128, 128, 128, 0.22);\n}\n\n/* \u5185\u5BB9\u9884\u89C8\uFF1A\u8FD9\u662F\"\u8BEF\u6321\u4F1A\u5F53\u573A\u73B0\u5F62\"\u7684\u5173\u952E\uFF0C\u6240\u4EE5\u7ED9\u5B83\u4E3B\u4F4D\u3001\u5141\u8BB8\u7701\u7565\u53F7 */\n.ccr-work__diag-preview {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.ccr-work__diag-age { flex: none; opacity: 0.7; }\n\n/* \u2550\u2550\u2550 \u534F\u4F5C\u611F\u77E5 B\uFF1A\u516C\u7EA6\u76D2 \u2550\u2550\u2550 */\n.ccr-box {\n  margin: 4px 0 0;\n  padding: 0;\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.ccr-box__item {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  padding: 6px 8px;\n  border-radius: 6px;\n  background: var(--ccr-panel-highlight);\n  font-size: 12px;\n}\n\n.ccr-box__topic {\n  flex: none;\n  padding: 0 5px;\n  font-size: 10px;\n  line-height: 15px;\n  border-radius: 4px;\n  background: rgba(128, 128, 128, 0.22);\n  opacity: 0.9;\n}\n\n.ccr-box__text {\n  flex: 1 1 auto;\n  min-width: 0;\n  word-break: break-word;\n}\n\n.ccr-box__who {\n  flex: none;\n  max-width: 26%;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  font-size: 10px;\n  opacity: 0.55;\n}\n\n.ccr-box__del {\n  flex: none;\n  padding: 0 4px;\n  font: inherit;\n  font-size: 14px;\n  line-height: 1;\n  color: inherit;\n  background: transparent;\n  border: 0;\n  cursor: pointer;\n  opacity: 0.35;\n}\n\n.ccr-box__del:hover { opacity: 1; }\n\n.ccr-box__empty {\n  margin-top: 4px;\n  padding: 8px;\n  font-size: 11px;\n  opacity: 0.55;\n  border-radius: 6px;\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-box__add {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  margin-top: 6px;\n}\n\n.ccr-input--topic { flex: none; width: 72px; }\n\n/* \u2550\u2550\u2550 \u5F85\u786E\u8BA4\u7684\u6743\u9650\u5347\u7EA7 \u2550\u2550\u2550 */\n.ccr-pending {\n  margin: 10px 0;\n  padding: 10px;\n  border: 1px solid var(--ccr-flow-color);\n  border-radius: 8px;\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-pending__text {\n  font-size: 12px;\n  line-height: 1.5;\n}\n\n/* \u2550\u2550\u2550 ConnectionPanel \u2550\u2550\u2550 */\n.ccr-panel {\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n  font-size: 13px;\n  min-width: 220px;\n}\n\n.ccr-panel__tabs {\n  display: flex;\n  gap: 4px;\n  padding: 8px;\n  border-bottom: 1px solid rgba(128, 128, 128, 0.2);\n}\n\n.ccr-panel__tab {\n  padding: 4px 12px;\n  border-radius: 4px;\n  cursor: pointer;\n  opacity: 0.6;\n  transition: opacity var(--ccr-fast);\n  user-select: none;\n}\n\n.ccr-panel__tab--active {\n  opacity: 1;\n  background: var(--ccr-panel-highlight);\n}\n\n.ccr-panel__list {\n  flex: 1;\n  overflow-y: auto;\n  padding: 4px 0;\n}\n\n.ccr-panel__empty,\n.ccr-panel__error {\n  padding: 12px;\n  opacity: 0.6;\n}\n\n.ccr-panel__error { color: #EF4444; opacity: 1; }\n\n.ccr-actions button {\n  font-size: 11px;\n  padding: 3px 8px;\n  border-radius: 4px;\n  border: 1px solid rgba(128, 128, 128, 0.35);\n  background: transparent;\n  color: inherit;\n  cursor: pointer;\n}\n\n.ccr-actions button:hover:not(:disabled) { background: var(--ccr-panel-highlight); }\n.ccr-actions button:disabled { opacity: 0.45; cursor: default; }\n\n/* \u2550\u2550\u2550 \u65E0\u969C\u788D / \u964D\u4F4E\u52A8\u6548 \u2550\u2550\u2550 */\n@media (prefers-reduced-motion: reduce) {\n  .ccr-flow__band,\n  .ccr-rail__flow,\n  .ccr-anchor--dragging .ccr-anchor__pulse { animation: none !important; }\n  .ccr-flow__particle { display: none !important; }\n}\n";
/**
 * 确保本插件的样式表存在，且内容是**本 bundle 的** CSS（缺则建、不符则更新）。
 *
 * 三件事缺一不可，实测少任何一件都会让面板突然变成裸 HTML：
 *   ① **打归属**。没有 `data-plugin` 的标签会在**别的插件物化时**被认领走
 *      （`claimStyles` 收 `style:not([data-plugin])`）；那个插件一热重载，
 *      框架就把我们的样式表当成它的删掉（`removeOwnedStyles`），而我们的
 *      客户端半区并没有重载 ⇒ 没人重新注入 ⇒ 面板裸奔。
 *   ② **不能"有标签就撒手"**。只查存在性会把旧代残留、被截断、被别的实例
 *      改写过的样式表当成好的。
 *   ③ **可重入**。`apply` 与面板挂载都会调它，重复调用必须只留一个标签。
 *
 * @returns 无；要注销请用 {@link injectStyles} 返回的函数。
 */
export declare function ensureStyles(): void;
/**
 * 把样式注入 document.head。
 *
 * @returns 注销函数 —— 只移除**本代创建**的标签；非浏览器环境下返回空操作。
 */
export declare function injectStyles(): () => void;
